<script setup>
import { onMounted, reactive, ref } from 'vue';
import { sellerAdmin } from '../features/aircraft-sales/services/aircraftSeller.service';
import { submissionStatuses } from '../features/aircraft-sales/sellerSchema';
const rows = ref([]), advisors = ref([]), count = ref(0), page = ref(0), query = ref(''), status = ref(''), selected = ref(null), busy = ref(false), error = ref(''), notice = ref('');
const edit = reactive({ submission_status:'new',admin_notes:'',assigned_advisor:null,followup:'' });
async function perform(action) { if (busy.value) return; busy.value=true; error.value=''; notice.value=''; try { await action(); } catch(e) { error.value=e.message; } finally { busy.value=false; } }
async function list() { const data=await sellerAdmin(`?${new URLSearchParams({q:query.value,status:status.value,page:String(page.value)})}`); rows.value=data.rows;count.value=data.count;advisors.value=data.advisors; }
async function detail(id) { const data=await sellerAdmin(`/${id}`); selected.value=data; Object.assign(edit,{ submission_status:data.record.submission_status,admin_notes:data.record.admin_notes,assigned_advisor:data.record.assigned_advisor,followup:'' }); }
function filter() { page.value=0;perform(list); }
function turn(delta) { page.value+=delta;perform(list); }
async function save() { await sellerAdmin(`/${selected.value.record.id}`,{ method:'PATCH',body:JSON.stringify(edit) });await detail(selected.value.record.id);await list();notice.value='Cambios guardados.'; }
async function download(file) { const data=await sellerAdmin(`/${selected.value.record.id}/files?file=${file.id}`); const link=document.createElement('a');link.href=data.url;link.rel='noopener noreferrer';link.target='_blank';link.click(); }
async function retry() { await sellerAdmin(`/${selected.value.record.id}/retry-email`,{method:'POST',body:'{}'});await detail(selected.value.record.id);notice.value='Notificaciones procesadas. Revisa el estado de cada correo.'; }
const labels={ aircraft_type:'Tipo',manufacturer:'Fabricante',model:'Modelo',manufacturing_year:'Año',registration:'Matrícula',serial_number:'Número de serie',total_time:'Horas totales',total_cycles:'Ciclos',country:'País',city:'Ciudad',asking_price:'Precio',currency:'Moneda',price_to_be_defined:'Precio por definir',aircraft_status:'Estado de aeronave',aircraft_notes:'Comentarios',contact_name:'Nombre',company:'Empresa',email:'Correo',phone:'Teléfono',relationship_to_aircraft:'Relación',preferred_contact_method:'Contacto preferido',privacy_accepted_at:'Aceptación de privacidad' };
const price = row => row.price_to_be_defined || row.asking_price == null ? 'Por definir' : `${row.currency} ${Number(row.asking_price).toLocaleString('es-MX')}`;
onMounted(()=>perform(list));
</script>
<template>
  <article class="seller-admin"><p class="eyebrow">SKY GROUP AVIATION / CONTROLLER</p><h1>Solicitudes para vender aeronaves</h1><p>Acceso exclusivo para cuentas autorizadas. Usa la sesión administrativa existente de Supabase.</p>
    <form class="filters" @submit.prevent="filter"><input v-model="query" aria-label="Buscar solicitudes" placeholder="Nombre, matrícula, modelo, correo o ubicación" /><select v-model="status" aria-label="Filtrar por estado"><option value="">Todos los estados</option><option v-for="item in submissionStatuses" :key="item">{{ item }}</option></select><button :disabled="busy">Buscar / actualizar</button></form>
    <p v-if="error" role="alert" class="error">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p><p v-if="busy" role="status">Procesando…</p>
    <div class="table-scroll"><table><thead><tr><th>Fecha</th><th>Propietario</th><th>Aeronave</th><th>Matrícula</th><th>Ubicación</th><th>Precio</th><th>Estado</th><th>Asesor</th><th>Acciones</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{ new Date(row.created_at).toLocaleDateString('es-MX') }}</td><td>{{ row.contact_name }}</td><td>{{ row.manufacturer }} {{ row.model }}</td><td>{{ row.registration }}</td><td>{{ row.city }}, {{ row.country }}</td><td>{{ price(row) }}</td><td>{{ row.submission_status }}</td><td>{{ advisors.find(a=>a.user_id===row.assigned_advisor)?.display_name || 'Sin asignar' }}</td><td><button :disabled="busy" @click="perform(()=>detail(row.id))">Consultar</button></td></tr><tr v-if="!rows.length && !busy"><td colspan="9">No hay solicitudes para mostrar.</td></tr></tbody></table></div>
    <nav class="pagination" aria-label="Páginas de solicitudes"><button :disabled="!page || busy" @click="turn(-1)">Anterior</button><span>{{ count }} solicitudes · Página {{ page + 1 }}</span><button :disabled="(page + 1) * 30 >= count || busy" @click="turn(1)">Siguiente</button></nav>
    <section v-if="selected" class="detail"><div class="detail-head"><h2>{{ selected.record.registration }} · {{ selected.record.contact_name }}</h2><button @click="selected=null">Cerrar</button></div><p>Referencia: {{ selected.record.id }}</p>
      <dl><div v-for="(label,key) in labels" :key="key"><dt>{{ label }}</dt><dd>{{ selected.record[key] ?? '—' }}</dd></div></dl>
      <h3>Documentos privados</h3><p v-if="!selected.files.length">Sin adjuntos.</p><ul><li v-for="file in selected.files" :key="file.id"><button :disabled="busy" @click="perform(()=>download(file))">Descargar {{ file.original_name }}</button></li></ul><small>Los enlaces autorizados caducan en 60 segundos.</small>
      <form @submit.prevent="perform(save)"><label>Estado<select v-model="edit.submission_status"><option v-for="item in submissionStatuses" :key="item">{{ item }}</option></select></label><label>Asesor<select v-model="edit.assigned_advisor"><option :value="null">Sin asignar</option><option v-for="a in advisors" :key="a.user_id" :value="a.user_id">{{ a.display_name }}</option></select></label><label>Notas internas<textarea v-model="edit.admin_notes" maxlength="12000" rows="4" /></label><label>Registrar seguimiento<textarea v-model="edit.followup" maxlength="4000" rows="3" /></label><button :disabled="busy">Guardar cambios</button></form>
      <h3>Seguimiento</h3><ul><li v-for="item in selected.followups" :key="item.id">{{ new Date(item.created_at).toLocaleString('es-MX') }} · {{ advisors.find(a=>a.user_id===item.author_id)?.display_name || item.author_id }}<p>{{ item.note }}</p></li></ul>
      <h3>Correos</h3><ul><li v-for="email in selected.emails" :key="email.kind">{{ email.kind === 'owner' ? 'Propietario' : 'Ventas' }}: {{ email.status }} {{ email.sent_at ? `· ${new Date(email.sent_at).toLocaleString('es-MX')}` : '' }}</li></ul><button :disabled="busy" @click="perform(retry)">Reintentar correos pendientes</button>
      <p class="review-note">La aceptación requiere revisión comercial. Ningún cambio de estado publica aeronaves en el inventario.</p>
    </section>
  </article>
</template>
<style scoped>
.seller-admin{padding:150px 30px 70px;max-width:1440px;margin:auto;color:#f0f4f8;min-height:70vh}.eyebrow{color:#c59b61;font-size:11px;letter-spacing:.15em}h1{font:400 clamp(28px,4vw,42px) var(--font-heading);margin:15px 0}p{font-size:14px;line-height:1.8;margin:12px 0}.filters{display:flex;gap:12px;margin:25px 0}.filters input{flex:1}input,select,textarea,button{font:inherit;padding:12px;border-radius:5px;border:1px solid #536273;min-height:44px}input,select,textarea{background:#fff;color:#071b30;min-width:0}button{background:#c59b61;color:#071b30;cursor:pointer;font-size:12px}button:disabled{opacity:.5;cursor:not-allowed}.table-scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:14px 10px;text-align:left;border-bottom:1px solid #ffffff26;white-space:nowrap}th{color:#d2b180}.pagination{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:20px 0;font-size:12px}.detail{border:1px solid #ffffff30;border-radius:8px;padding:25px;margin-top:30px}.detail-head{display:flex;justify-content:space-between;gap:15px}h2{font-size:22px}h3{margin:25px 0 15px}.detail dl{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:25px 0}.detail dt{color:#c59b61;font-size:11px}.detail dd{font-size:14px;overflow-wrap:anywhere;white-space:pre-wrap;margin-top:4px}.detail form{display:grid;gap:16px;margin-top:25px}.detail label{display:grid;gap:7px;font-size:13px}.detail li{margin:12px 0;white-space:pre-wrap;overflow-wrap:anywhere}.detail ul{list-style:none}.error{color:#ffb5b0}.review-note{color:#d2b180}small{font-size:11px}@media(max-width:760px){.seller-admin{padding:120px 18px 50px}.filters{flex-direction:column}.detail{padding:16px}.detail dl{grid-template-columns:1fr}.detail-head{flex-direction:column}}
</style>
